// Package store is FleetDeck's data-access layer. It owns the Postgres
// connection pool and exposes protocol-typed CRUD methods to the hub and node
// daemons. SQL is generated by sqlc into the private internal/store/sqlcgen
// subpackage; the public API never leaks sqlc or pgx types.
//
// The public API speaks internal/protocol types (the wire contract). See
// models.go for the DB-row <-> protocol conversion convention.
package store

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"

	"fleetdeck/internal/store/sqlcgen"
)

// Store owns the connection pool and the protocol-typed query set.
type Store struct {
	pool *pgxpool.Pool
	q    *Queries
}

// New connects to Postgres at dsn, verifies the connection, and returns a
// ready-to-use Store. The caller owns the lifecycle and must call Close.
func New(ctx context.Context, dsn string) (*Store, error) {
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		return nil, fmt.Errorf("store: connect: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("store: ping: %w", err)
	}
	return &Store{pool: pool, q: newQueries(sqlcgen.New(pool))}, nil
}

// Close releases the connection pool. Safe to call once; the Store must not be
// used afterwards.
func (s *Store) Close() {
	s.pool.Close()
}

// Pool exposes the underlying pgx pool for callers that need raw access (e.g.
// health checks). Prefer the protocol-typed methods.
func (s *Store) Pool() *pgxpool.Pool {
	return s.pool
}

// Queries returns the protocol-typed query set bound to the pool. Use this for
// non-transactional reads/writes; use WithTx for multi-statement work.
func (s *Store) Queries() *Queries {
	return s.q
}

// Queries wraps sqlc's generated *sqlcgen.Queries and converts DB rows to
// protocol.* at the boundary. Method set is defined across node.go,
// workspace.go, task.go, subtask.go, session.go, message.go and event.go.
type Queries struct {
	q *sqlcgen.Queries
}

func newQueries(q *sqlcgen.Queries) *Queries {
	return &Queries{q: q}
}
